import { html } from 'lit-html';

export default {
  title: 'Components/EmailInput',
  component: 'bfl-email-input',
  tags: ['autodocs'],
  argTypes: {
    name: { control: 'text', description: 'Name of the input field', defaultValue: 'email' },
    label: { control: 'text', description: 'Label for the input field', defaultValue: 'Email Address' },
    domain: { control: 'text', description: 'Domain to append to the input value', defaultValue: '@example.com' },
    placeholder: { control: 'text', description: 'Placeholder text for the input field', defaultValue: 'Enter your email' },
    value: { control: 'text', description: 'Initial value of the input field', defaultValue: '' },
    isRequired: { control: 'boolean', description: 'Marks the field as required', defaultValue: false },
    hasCustomError: { control: 'boolean', description: 'Indicates if there is a custom error', defaultValue: false },
    customErrorMessage: { control: 'text', description: 'Custom error message to display', defaultValue: 'Invalid email address' },
  },
};

const Template = ({ name, label, domain, placeholder, value, isRequired, hasCustomError, customErrorMessage }) => html`
  <bfl-email-input
    name="${name}"
    label="${label}"
    domain="${domain}"
    placeholder="${placeholder}"
    .value="${value}"
    .isRequired="${isRequired}"
    .hasCustomError="${hasCustomError}"
    .customErrorMessage="${customErrorMessage}"
  ></bfl-email-input>
`;

export const Default = Template.bind({});
Default.args = {
  name: 'email',
  label: 'Email Address',
  domain: '@example.com',
  placeholder: 'Enter your email',
  value: '',
  isRequired: false,
  hasCustomError: false,
  customErrorMessage: '',
};

export const RequiredField = Template.bind({});
RequiredField.args = {
  ...Default.args,
  isRequired: true,
};

export const WithCustomError = Template.bind({});
WithCustomError.args = {
  ...Default.args,
  hasCustomError: true,
  customErrorMessage: 'Please enter a valid email address',
};

export const PreFilledValue = Template.bind({});
PreFilledValue.args = {
  ...Default.args,
  value: 'user',
};

export const WithDomain = Template.bind({});
WithDomain.args = {
  ...Default.args,
  domain: '@mydomain.com',
};
